# Music section → data/music.js. No lyrics are reproduced: only background, meaning questions and related expressions.
import json, os, urllib.parse

S = []
def song(l, title, artist, year, about, qs, ex):
    S.append({"l": l, "title": title, "artist": artist, "year": year,
              "url": "https://www.youtube.com/results?search_query=" + urllib.parse.quote_plus(f"{artist} {title} official"),
              "about": about, "q": [{"q": q, "o": o, "e": e} for q, o, e in qs], "ex": ex})

