if __name__ == "__main__":
    from collections import Counter
    print(Counter(s["l"] for s in S))
    for s in S:
        assert len(s["q"]) == 3 and len(s["ex"]) == 4, s["title"]
    root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    open(os.path.join(root, "data", "music.js"), "w").write("// Music: real songs (link to YouTube search), background, meaning questions and related expressions. No lyrics.\nDATA.music = " + json.dumps(S, ensure_ascii=False, indent=0) + ";\n")
